<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientM2mTokenTtlSecondsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientM2mTokenTtlSecondsAccessor trait.
 *
 * Covers null default, string/VO assignment via withM2mTokenTtlSeconds,
 * getM2mTokenTtlSeconds/m2mTokenTtlSeconds accessors, and isM2mTokenTtlSecondsChanged with/without original.
 */
class TrustedClientM2mTokenTtlSecondsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withM2mTokenTtlSeconds creates a new instance with the M2mTokenTtlSeconds set
     * from a string value, and getM2mTokenTtlSeconds returns the primitive string.
     */
    public function testWithM2mTokenTtlSecondsFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientM2mTokenTtlSecondsAccessorUnitTest();

        // Act
        $result = $holder->withM2mTokenTtlSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getM2mTokenTtlSeconds());
    }
    /**
     * Asserts that withm2mTokenTtlSeconds has access to the value object
     * from a string value, and getM2mTokenTtlSeconds returns the primitive string.
     */
    public function testWithM2mTokenTtlSecondsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientM2mTokenTtlSecondsAccessorUnitTest();

        // Act
        $result = $holder->withM2mTokenTtlSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->m2mTokenTtlSeconds()->value());
    }
    public function testChangedM2mTokenTtlSeconds(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientM2mTokenTtlSecondsAccessorUnitTest()->withM2mTokenTtlSeconds(1);
        $original = $holder->withM2mTokenTtlSeconds(1);
        $same = $holder->withM2mTokenTtlSeconds(1);
        $modified = $holder->withM2mTokenTtlSeconds(2);

        // Act
        $withSame = $original->isM2mTokenTtlSecondsChanged($same);
        $withDiferent = $original->isM2mTokenTtlSecondsChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientM2mTokenTtlSecondsAccessorUnitTest
{
    use TrustedClientM2mTokenTtlSecondsAccessor;
}
